import{_ as e,o as s,c as p,a3 as r}from"./chunks/framework.BwzYn71E.js";const k=JSON.parse('{"title":"视频文案","description":"","frontmatter":{"translationSource":{"title":"视频文案","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=B3tojB4zGjZ30BLLdL9qvK","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/all-condition-xircon-video-script"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/all-condition-xircon-video-script"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/all-condition-xircon-video-script"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/all-condition-xircon-video-script"}]]},"headers":[],"relativePath":"zh/all-condition-xircon-video-script.md","filePath":"zh/page-B3tojB4zGjZ30BLLdL9qvK.md"}'),n={name:"zh/all-condition-xircon-video-script.md"};function o(t,a,l,i,c,d){return s(),p("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="视频文案" tabindex="-1">视频文案 <a class="header-anchor" href="#视频文案" aria-label="Permalink to &quot;视频文案&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-08T14-43-43-693Z-b04528fe" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-08. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-08T14:43:45.228Z">2026-11-08</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>B3tojB4zGjZ30BLLdL9qvK</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=B3tojB4zGjZ30BLLdL9qvK" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-RDbBJi6vkeN255vNGHDFry"></span></p><h2 id="引入" tabindex="-1">引入 <a class="header-anchor" href="#引入" aria-label="Permalink to &quot;引入&quot;">​</a></h2><p>在我们的自适应最大毛产蓝图和许多其他的蓝图中，壤晶模块会存在一个问题，就是在长时间不输入息壤或息壤不足时，容易出现自锁无法自动解除。我们可以通过一些方法（比如我们正在做的全新满仓震荡方案）规避息壤不足的问题，但现在经过我们的研究推出了这一款抗一切壤晶，能够一键解决所有可能出现的问题。</p><p><span class="mark-grey">#言 文案<br> 随着1.2的壤晶模块发展至今，大多数大家所看到的壤晶模块大都具备抗壤晶满仓的能力，但是如果原料供给不足（画面中出现 清水 污水 蓝铁粉末 息壤），仍会出现“自锁”使得反应速率永久性下降。诚然在正常的工况中很少出现原料不足，只要教会大家怎么修好就可以了，毕竟开一下自动清理再关上也算不上什么麻烦事<br> 但那是弱者的思维！（一张众所周知的配图）<br> 事实上，只要我们设计的壤晶模块能抵抗一切恶劣工况，那这个问题自然就不存在了，顺便终结了中电生产不如小电生产可靠的历史。于是我们设计了这款“抗一切壤晶线”</span></p><p><span id="source-block-B2oIxTvH7Xxbz4jsN9yLX2"></span></p><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h2><p>在一切外部扰动情况下（<span class="mark-red">有/无净水节点壤晶废液</span>，<span class="mark-orange">是/否壤晶爆仓</span>，<span class="mark-yellow">只缺息壤/只缺清水/只缺污水/只缺蓝铁粉/同时缺息壤和清水/同时缺息壤和污水/同时缺息壤和蓝铁粉/同时缺清水和污水/同时缺息壤和污水和/同时缺清水和污水/同时缺息壤清水污水/同时缺息壤清水蓝铁粉/同时缺息壤污水蓝铁粉/同时缺清水污水蓝铁粉/只有息壤/只有清水/只有污水/只有蓝铁粉</span>）都不会发生自锁，不会产生任何原料浪费，能自行收敛到给定输入下的最大产出，不会掉速，并且可以在提供充足的输入原料后或壤晶爆仓状态解除后自动恢复正常生产</p><p>省电（3扩容反应池2反应池，共400电力，可同时兼容药液生产）</p><p><span class="mark-grey">#言 评论<br> 好像有点语病</span></p><p><span id="source-block-ImY1wA0pyXFZ4wWMXGiE6D"></span></p><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><p>自锁原理：<span class="mark-green">壤晶废液</span>与<span class="mark-purple">污水</span>同时达到50存量且正在进行壤晶废液反应（息壤液+污水→壤晶废液+惰性）和壤晶反应（壤晶废液+蓝铁粉→壤晶+污水）时发生自锁。</p><p>息壤不足自锁原理：息壤不足，且连续输入壤晶废液，壤晶废液生产污水导致两者都达到50，但是没有壤晶废液反应，没有自锁；输入息壤消耗1污水开始壤晶废液反应，壤晶反应完成产生1污水使污水变成50，再消耗2壤晶废液开始壤晶反应；连续1s输入2壤晶废液使壤晶废液变成50，此时双50且有壤晶反应和壤晶废液反应，发生自锁。相应的，输入<span class="mark-purple">污水</span>则不会自锁。</p><p>壤晶堵满自锁原理：壤晶堵后，壤晶反应堵死，连续输入污水，生产壤晶的反应池依旧正常进行壤晶废液反应，导致两者达到50后自然进入自锁。相应的，输入<span class="mark-green">壤晶废液</span>则不会自锁。</p><p>自动解锁原理：流出<span class="mark-green">壤晶废液</span>或<span class="mark-purple">污水</span>即可自动解除自锁。但当输出频率不足时，会出现自锁-解锁反复出现，导致的无法达成最大速率。</p><p>抗一切壤晶线原理：让污水保持流动从而永远无法堵满，于是无法触发由壤晶废液和污水均堵满导致的扩容反应池自锁，也就是说时刻都能解除自锁状态，即不会出现自锁情况。与此同时污水的流动能给壤晶反应提供足够的空位。</p><p><span class="mark-grey">#言 评论<br> 是不是太冗长了</span></p><p><span class="mark-grey">#言 文案<br> 自锁的发生→自锁的解除<br> 污水输出与壤晶生产的对轴——能否达到满速/能否在掉速后回到满速</span></p><p><span id="source-block-G4ZqSXlTAuffakno2II1eB"></span></p><h2 id="使用教程" tabindex="-1">使用教程 <a class="header-anchor" href="#使用教程" aria-label="Permalink to &quot;使用教程&quot;">​</a></h2><p>通过暗管接入60清水（可过量），60污水（可过量）（最好与赤铜解耦，听不懂就当我没说），30液化息壤（可过量），0/12壤晶废液（可过量）</p><p><span class="mark-grey">#言 评论<br> 赤铜解耦谁看得懂啊，我觉得不要提，之后还会有视频正儿八经地介绍“为什么可以不销毁最终产物”。好吧如果你非要提不如顺便把解耦模块给出来，如果你不提解耦模块具体销毁什么说污水解耦有点太发散了。</span></p><p>已接入90息壤，90蓝铁粉末</p><p>正常情况生产75（无净水节点）/81（有净水节点）壤晶</p><p><span id="source-block-gAZAiMzy7xC6vLFMe3NjDK"></span></p><h2 id="这就是终点吗" tabindex="-1">这就是终点吗 <a class="header-anchor" href="#这就是终点吗" aria-label="Permalink to &quot;这就是终点吗&quot;">​</a></h2><p>当然不可能。随便说说都有不完美的地方：当壤晶满仓时无法输出内部息壤液，常态运行时反应池利用率没拉满（展示壤晶小反？）</p><p><span id="source-block-yJdofzx1Eu4IOVqZbl05PN"></span></p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>这是我们第一次单独挑出来一个基建模块做成视频来给大家同步我们最新的研发成果，希望大家多多评论，给我们提点建议，最后求个三连谢谢大家！</p><p><span class="mark-grey">#言 评论<br> 是第一次吗？百亿不是做了几个自控装置的讲解吗（</span></p><p><span class="mark-grey">斯改号上的第一次（（</span></p></div>',1)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
